import re
"""Textos editoriais originais em português, com referências oficiais por seção.

As animações são ilustrações autorais da interface, sem trechos do anime.
Não atribui números de força, alcance ou rank ausentes das fontes.
"""
import json,pathlib,sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
OUT=ROOT/'data/editorial';OUT.mkdir(exist_ok=True)
BASE='https://naruto-official.com/en/news/'
BIOS=[];HISTORY=[]
def bio(name,title,intro,style,articles,chapters):
    chars=json.loads((ROOT/'data/processed/json/personagens.json').read_text(encoding='utf-8'))
    matches=[c for c in chars if c['nome']==name]
    assert len(matches)==1,name
    cid=matches[0]['personagem_id']
    BIOS.append({'personagem_id':cid,'titulo':title,'resumo':intro,'estilo':style,'fontes':' | '.join(BASE+a for a in articles),'tipo_texto':'Síntese editorial original em português'})
    for i,(phase,heading,text,spoiler,article) in enumerate(chapters):
        HISTORY.append({'personagem_id':cid,'ordem':i,'fase':phase,'titulo':heading,'texto':text,'revelacao':spoiler,'url_fonte':BASE+article})

bio('Naruto Uzumaki','Um sonho maior que a solidão','Um garoto de Konoha transforma a busca por reconhecimento em um compromisso com as pessoas ao seu redor. Persistência, amizade e a vontade de ser Hokage conduzem seu caminho.','naruto',['01_1610','01_1611'],[
 ('Origens','A criança e a Vila da Folha','Filho de Minato Namikaze e Kushina Uzumaki, Naruto cresce carregando a Nove-Caudas. O medo dos moradores o isola. O acolhimento de Iruka abre espaço para que ele se reconheça como alguém capaz de construir o próprio futuro.',False,'01_1610'),
 ('Naruto clássico','Os primeiros laços','Ao integrar o Time 7 com Sasuke, Sakura e Kakashi, ele descobre o peso das promessas e do trabalho em equipe. As missões e o Exame Chūnin transformam a rivalidade em aprendizado, e o encontro com Jiraiya amplia sua formação.',False,'01_1610'),
 ('Shippuden','Reconhecimento e responsabilidade','O treinamento com Jiraiya fortalece sua determinação. Depois do confronto com Pain, Naruto passa a ser reconhecido como protetor da vila. Sua resposta à dor procura romper a repetição da violência, sem abandonar os vínculos que construiu.',True,'01_1610'),
 ('A Grande Guerra','De adversário a parceiro','Com ajuda de Killer B e do encontro com a memória de Kushina, Naruto enfrenta o próprio conflito com a Nove-Caudas. Sua relação com Kurama evolui, e ele atua ao lado da Aliança Shinobi durante a guerra.',True,'01_1611'),
 ('Legado','A promessa encontra o futuro','O confronto final com Sasuke encerra uma longa disputa e permite a reconciliação. Anos depois, Naruto assume como Sétimo Hokage. O desejo de reconhecimento se transforma na responsabilidade de cuidar de toda a vila.',True,'01_1611')])
bio('Itachi Uchiha','O peso do silêncio','Um prodígio do clã Uchiha, marcado pela guerra e por decisões que colocam em conflito a família, a vila e o amor pelo irmão.','itachi',['01_1814'],[
 ('Infância','Talento em um mundo de guerra','A violência presenciada na infância faz Itachi desejar a paz. Sua formação avança rapidamente: ele se destaca na Academia e ingressa nas estruturas de defesa de Konoha ainda jovem.',False,'01_1814'),
 ('O clã Uchiha','Entre duas lealdades','A preparação de um golpe do clã o coloca entre a família e a liderança da vila. A missão que recebe e suas escolhas desencadeiam a tragédia dos Uchiha, enquanto Sasuke permanece no centro de sua preocupação.',True,'01_1814'),
 ('Akatsuki','Um irmão visto à distância','Como membro da Akatsuki, Itachi apresenta uma imagem ameaçadora. Seu encontro definitivo com Sasuke muda o entendimento que o irmão tinha do passado e expõe um conflito muito mais amplo que a vingança pessoal.',True,'01_1814'),
 ('A Grande Guerra','O último gesto','Reanimado durante a guerra, recupera sua autonomia graças ao poder deixado por Shisui. Ele se une a Sasuke para interromper a Reanimação e, ao se despedir, abandona as manipulações para reconhecer abertamente o amor pelo irmão.',True,'01_1814')])
bio('Sasuke Uchiha','Laços, ruptura e reencontro','O sobrevivente de uma tragédia familiar busca respostas e poder. Sua ligação com Naruto e o Time 7 acompanha uma trajetória de escolhas difíceis.','sasuke',['01_1856','01_1858'],[
 ('Origens','A sombra do irmão','Sasuke cresce admirando Itachi e procurando o reconhecimento do pai, Fugaku. A destruição do clã muda sua infância e transforma o desejo de alcançar o irmão em uma busca por vingança.',False,'01_1856'),
 ('Naruto clássico','O Time 7 e a partida','A convivência com Naruto, Sakura e Kakashi cria vínculos reais. Ainda assim, a sensação de estar distante de seu objetivo o aproxima da promessa de poder de Orochimaru e o leva a deixar Konoha.',True,'01_1856'),
 ('Shippuden','A verdade muda o alvo','Depois de enfrentar Itachi, Sasuke recebe revelações sobre o massacre e a atuação da vila. A descoberta redireciona sua revolta e aprofunda o conflito entre o afeto que preserva e os caminhos que decide seguir.',True,'01_1858'),
 ('Legado','Reconstruir o próprio caminho','Na fase final da guerra, volta a lutar com o Time 7. A disputa decisiva com Naruto termina em reconhecimento mútuo. Em seguida, parte em uma jornada de reparação, iniciando uma relação diferente com a vila e com os antigos companheiros.',True,'01_1858')])
bio('Sakura Haruno','Florescer também é uma escolha','Integrante do Time 7, Sakura encontra no controle de chakra, na medicina e na disciplina de Tsunade uma forma própria de proteger seus companheiros.','sakura',['01_1743'],[
 ('Infância','Confiança que se constrói','As inseguranças da infância dão lugar a uma postura mais firme com o apoio de Ino. Na Academia e no Time 7, Sakura começa a descobrir como participar das missões e sustentar suas próprias escolhas.',False,'01_1743'),
 ('Formação','A discípula da Quinta Hokage','Ao reconhecer os próprios limites, pede para ser treinada por Tsunade. Seu controle de chakra favorece o aprendizado de ninjutsu médico e o desenvolvimento de uma força concentrada em golpes precisos.',False,'01_1743'),
 ('Shippuden','A linha de frente','A experiência com Chiyo contra Sasori demonstra a evolução de sua formação. Durante a guerra, Sakura atua no apoio médico e volta a combater ao lado de Naruto e Sasuke como integrante de um Time 7 reunido.',True,'01_1743'),
 ('Legado','Cuidar da próxima geração','Depois do conflito, segue ligada à medicina e à reconstrução. Sua relação com Sasuke e a maternidade de Sarada ampliam os vínculos entre sua história pessoal e a nova geração de Konoha.',True,'01_1743')])
bio('Kakashi Hatake','A força de não abandonar ninguém','O líder do Time 7 combina experiência, análise e um passado de perdas. Sua formação como professor passa pela importância que dá aos companheiros.','kakashi',['01_1903','01_1904'],[
 ('Origens','Um talento cercado por perdas','Filho de Sakumo Hatake, Kakashi se destaca cedo na formação ninja. A morte do pai e os acontecimentos vividos com Obito e Rin marcam sua maneira de lidar com regras, responsabilidade e amizade.',False,'01_1903'),
 ('Time 7','Ensinar além das técnicas','Ao receber Naruto, Sasuke e Sakura, estabelece o trabalho em equipe como fundamento. Suas experiências e o Sharingan o tornam uma referência para os alunos, embora ensinar também o obrigue a enfrentar os próprios limites.',False,'01_1903'),
 ('A Grande Guerra','Reencontrar o passado','O confronto com Obito faz Kakashi revisitar perdas e promessas. Ele mantém sua confiança em Naruto, participa da luta final e presencia o reencontro de seus três alunos depois da disputa no Vale do Fim.',True,'01_1904'),
 ('Legado','O Sexto Hokage','Nomeado Sexto Hokage, assume a tarefa de conduzir Konoha em um período de reconstrução e cooperação entre vilas. Mais tarde, entrega essa responsabilidade a Naruto.',True,'01_1904')])
bio('Minato Namikaze','Um instante pode proteger uma vida','Conhecido como Relâmpago Amarelo de Konoha, o Quarto Hokage deixa uma história ligada à velocidade, ao ensino e à proteção da família.','minato',['01_1681','01_1610'],[
 ('Formação','Professor e Hokage','Minato conduz o time de Kakashi, Obito e Rin antes de assumir a liderança de Konoha. Sua trajetória associa a precisão em combate à responsabilidade por aqueles que estão sob seus cuidados.',False,'01_1681'),
 ('Nascimento de Naruto','Uma decisão extrema','Durante o ataque da Nove-Caudas, ele e Kushina procuram proteger Naruto e a vila. Minato sela parte do poder da besta no filho e confia a ele a possibilidade de um futuro diferente.',True,'01_1610'),
 ('A Grande Guerra','O reencontro possível','Reanimado com os antigos Hokage, volta a lutar pela vila e encontra Naruto já crescido. A participação na guerra permite que acompanhe o filho e se despeça dele no aniversário, retomando seu papel de pai.',True,'01_1681')])
bio('Hinata Hyūga','Coragem que cresce em silêncio','Herdeira de uma família tradicional, Hinata procura construir confiança sem perder a gentileza. Sua determinação se fortalece ao observar a persistência de Naruto.','hinata',['01_1668'],[
 ('Origens','As expectativas do clã','Nascida na família principal dos Hyūga, enfrenta cobranças para desenvolver suas habilidades. A timidez dificulta esse processo, mas não apaga sua vontade de melhorar e encontrar um caminho pessoal.',False,'01_1668'),
 ('Naruto clássico','Aprender a se afirmar','A convivência com sua equipe e o confronto com Neji colocam à prova sua confiança. Inspirada por Naruto, passa a enfrentar situações das quais antes recuaria.',False,'01_1668'),
 ('Shippuden','Escolher permanecer ao lado','Sua disposição para proteger Naruto se torna explícita durante o ataque de Pain. Na guerra, ela compartilha perdas e reafirma a decisão de seguir em frente com aqueles que ama.',True,'01_1668'),
 ('Legado','Família e continuidade','Sua relação com Naruto se transforma em uma família. Como mãe de Boruto e Himawari, mantém a ligação entre a história dos Hyūga e a geração que cresce depois da guerra.',True,'01_1668')])
bio('Gaara','Da solidão à responsabilidade','O shinobi da Areia encontra nos laços humanos uma alternativa à violência e transforma a própria experiência de isolamento em liderança.','gaara',['01_1688'],[
 ('Infância','A criança temida','Com Shukaku selado em seu corpo, Gaara vive cercado pelo medo dos moradores de Suna. A dificuldade em controlar seu poder e os conflitos familiares aprofundam sua solidão.',False,'01_1688'),
 ('Encontro com Naruto','Outra forma de existir','O confronto com Naruto permite que reconheça uma experiência semelhante à sua. Aos poucos, substitui a busca por confirmação através da violência pelo desejo de proteger outras pessoas.',False,'01_1688'),
 ('Shippuden','O Kazekage e a Aliança','Como Kazekage, passa a ocupar uma posição de responsabilidade. Durante a guerra, lidera e inspira shinobi de vilas diferentes, defendendo vínculos que ultrapassam antigas rivalidades.',True,'01_1688'),
 ('Revelações','A proteção que permaneceu','O reencontro com o pai revela que a areia que o protege expressa o amor de sua mãe, Karura. A descoberta oferece uma nova compreensão de sua infância e do afeto que julgava nunca ter recebido.',True,'01_1688')])
bio('Jiraiya','Ensinar também é acreditar','Um dos Sannin, Jiraiya liga a experiência de viajante e escritor à formação de alunos que carregariam suas perguntas sobre o futuro do mundo ninja.','jiraiya',['01_1643'],[
 ('O mestre','Uma geração após a outra','Sua história de professor inclui Minato e, anos depois, Naruto. O vínculo com os sapos e a experiência como shinobi acompanham uma procura por alguém capaz de transformar o mundo.',False,'01_1643'),
 ('Treinamento','A herança do Rasengan','Ao conhecer Naruto, orienta seu uso de chakra e o treinamento de invocação. Mais tarde ensina o Rasengan, técnica criada por Minato, ligando a formação do filho à história do pai.',False,'01_1643'),
 ('Shippuden','O risco de buscar respostas','A investigação da Akatsuki leva Jiraiya ao confronto com Pain. As informações que consegue transmitir e a confiança depositada em Naruto permanecem como parte de sua contribuição para os acontecimentos seguintes.',True,'01_1643')])
bio('Obito Uchiha','Entre o sonho e a perda','Um jovem que deseja ser Hokage tem seu caminho alterado pela guerra. Seus vínculos com Kakashi, Rin e Minato atravessam tanto suas escolhas quanto suas rupturas.','obito',['01_1706'],[
 ('Time Minato','Um companheiro antes de tudo','Obito integra a equipe de Minato com Kakashi e Rin. Apesar da rivalidade com Kakashi, demonstra a disposição de colocar os companheiros acima das regras da missão.',False,'01_1706'),
 ('A ponte','O presente e a sobrevivência','Gravemente ferido ao proteger Kakashi, entrega a ele seu Sharingan. Sua sobrevivência e a influência de Madara o aproximam de um projeto de mundo ilusório construído para escapar da dor.',True,'01_1706'),
 ('A Grande Guerra','Escolher de novo','Como figura central do conflito, enfrenta Kakashi e Naruto. O choque com seus antigos ideais abre caminho para uma mudança: em seus últimos atos, volta a priorizar os companheiros e ajuda a protegê-los.',True,'01_1706')])
bio('Madara Uchiha','O sonho de paz que tomou outro rumo','Nascido entre conflitos de clãs, Madara compartilha com Hashirama um desejo de mudança. A divergência entre seus caminhos marca a história do mundo shinobi.','madara',['01_1663'],[
 ('Origens','Um encontro em tempos de guerra','Como herdeiro Uchiha, cresce em um mundo de confrontos e perdas. Sua amizade com Hashirama nasce antes que os dois possam superar as obrigações impostas pelos clãs.',False,'01_1663'),
 ('Konoha','Fundação e ruptura','A aproximação entre Uchiha e Senju permite o surgimento de Konoha. As diferenças sobre o futuro da vila, porém, afastam Madara de Hashirama e conduzem os antigos amigos a um confronto.',True,'01_1663'),
 ('O plano','Uma paz imposta','Madara transmite a Obito sua ambição de criar um mundo de sonhos. De volta durante a guerra, procura realizar o Tsukuyomi Infinito, colocando a própria ideia de paz acima da liberdade dos demais.',True,'01_1663'),
 ('Desfecho','O antigo companheiro','A traição de Zetsu interrompe seu projeto. Ao fim, conversa com Hashirama sobre o que ambos não conseguiram realizar, reencontrando por um instante a ligação anterior à rivalidade.',True,'01_1663')])
bio('Hashirama Senju','Imaginar uma vila antes de ela existir','O Primeiro Hokage procura uma alternativa à guerra entre clãs. Sua relação com Madara e a fundação de Konoha dão forma a esse projeto.','hashirama',['01_1627'],[
 ('Origens','Crianças em um mundo de guerra','Nascido entre os Senju, Hashirama presencia cedo o custo dos confrontos. O encontro com Madara aproxima dois jovens que imaginam um futuro no qual as crianças não precisem se enfrentar.',False,'01_1627'),
 ('A fundação','Um lugar para construir laços','A aliança entre os clãs permite a criação da Vila da Folha. Como Primeiro Hokage, Hashirama passa a defender uma organização que preserve a população e ofereça continuidade às novas gerações.',False,'01_1627'),
 ('Conflito e legado','O sonho confiado ao futuro','A ruptura com Madara culmina em uma batalha que transforma a paisagem. Mesmo depois disso, Hashirama mantém a busca por cooperação entre vilas e procura aproximar seus líderes em uma reunião dos Kage.',True,'01_1627')])
bio('Tobirama Senju','Dar estrutura ao futuro','O Segundo Hokage combina estratégia, criação de técnicas e organização institucional para consolidar a vila que ajudou o irmão a construir.','tobirama',['01_1694'],[
 ('Os Senju','Pragmatismo em meio ao conflito','Ao lado de Hashirama, Tobirama desenvolve uma visão estratégica para enfrentar as guerras dos clãs. Procura transformar a intenção de paz em regras e acordos duradouros.',False,'01_1694'),
 ('Segundo Hokage','Instituições e técnicas','Ao assumir a liderança, participa da estruturação de Konoha e da formação de sua próxima geração. Sua contribuição técnica inclui Clones das Sombras, Deus Voador do Trovão e Reanimação.',False,'01_1694'),
 ('Legado','Confiar a vila aos que ficam','Em uma situação sem saída, escolhe servir de distração para que os subordinados escapem. Antes de partir, indica Hiruzen como sucessor e coloca a continuidade da vila nas mãos dos mais jovens.',True,'01_1694')])
bio('Shisui Uchiha','A vontade que continua em outra pessoa','Reconhecido pela velocidade e pelo poder ocular, Shisui exerce influência decisiva sobre a maneira como Itachi entende a proteção da vila.','shisui',['01_1625'],[
 ('Amizade','O irmão escolhido','A convivência com Itachi reúne treinamento, confiança e preocupação com o destino dos Uchiha. A amizade ajuda a formar os ideais que Itachi carregaria consigo.',False,'01_1625'),
 ('O clã','Proteger sem buscar reconhecimento','Diante da crise entre o clã e a vila, Shisui procura uma saída que preserve a paz. Sua decisão de confiar o futuro a Itachi se torna uma das marcas mais profundas na vida do amigo.',True,'01_1625'),
 ('Legado','Um poder que alcança a guerra','O olho que deixa a Itachi acaba ligado a Naruto. O Kotoamatsukami permite que Itachi rompa o controle da Reanimação, dando a Shisui uma influência que permanece mesmo depois de sua morte.',True,'01_1625')])
bio('Neji Hyūga','O destino também pode ser questionado','O talento de Neji se desenvolve sob as limitações impostas à família secundária dos Hyūga. Seus encontros colocam em dúvida a ideia de um futuro inevitável.','neji',['01_1817'],[
 ('O clã','Uma marca desde a infância','Filho de Hizashi, Neji pertence à família secundária dos Hyūga. A marca que recebe e a perda do pai alimentam sua revolta contra as hierarquias que parecem determinar sua vida.',False,'01_1817'),
 ('Exame Chūnin','A convicção colocada à prova','O duelo com Hinata expõe sua amargura. Depois, Naruto enfrenta não apenas sua técnica, mas a crença de que ninguém consegue mudar o próprio destino.',False,'01_1817'),
 ('Mudança','Escolher quem proteger','Ao conhecer melhor a história do pai e reconstruir seus vínculos, Neji passa a agir segundo suas próprias decisões. Sua atuação na guerra expressa essa mudança na forma de compreender liberdade e proteção.',True,'01_1817')])
bio('Might Guy','A disciplina de continuar tentando','Especialista em taijutsu e líder apaixonado, Guy transforma os desafios diários em um compromisso com o crescimento dos alunos e com a amizade.','guy',['01_1673'],[
 ('O professor','Ensinar pelo exemplo','Guy incentiva Lee a acreditar no valor do próprio esforço. O treinamento intenso vem acompanhado de promessas, metas pessoais e disposição para apoiar o aluno em seus momentos mais difíceis.',False,'01_1673'),
 ('Rivalidade','Kakashi como referência','Sua rivalidade com Kakashi atravessa a vida cotidiana e as missões. As disputas constantes funcionam como uma forma de motivação e como expressão de um vínculo duradouro.',False,'01_1673'),
 ('A Grande Guerra','Levar o esforço ao limite','Diante de Madara, Guy recorre aos Oito Portões para proteger seus aliados. A decisão concentra o risco físico de seu estilo de combate e a determinação que orienta sua trajetória.',True,'01_1673')])
bio('Shikamaru Nara','Pensar à frente para proteger os outros','O estrategista de Konoha costuma preferir a tranquilidade, mas assume responsabilidades quando seus companheiros dependem de suas decisões.','shikamaru',['01_1910'],[
 ('Formação','O olhar do estrategista','Integrante do time de Asuma com Ino e Chōji, Shikamaru se destaca pela leitura do campo de batalha. Seu uso das sombras acompanha a capacidade de antecipar movimentos e preparar alternativas.',False,'01_1910'),
 ('Responsabilidade','Aprender com as perdas','As missões de liderança mostram que uma estratégia envolve vidas, e não apenas um problema a resolver. A perda de Asuma aprofunda seu compromisso com o time e com aqueles que precisam de proteção.',True,'01_1910'),
 ('Legado','Apoiar a próxima geração','Durante a guerra, contribui para a coordenação dos aliados. Mais tarde, continua ligado à liderança da vila e ao apoio a Naruto, levando adiante os ensinamentos de seus mestres.',True,'01_1910')])
bio('Boruto Uzumaki','O legado não escolhe todo o caminho','Filho do Sétimo Hokage, Boruto cresce em uma vila mais pacífica, mas precisa descobrir como construir uma identidade além da história do pai.','boruto',['01_1745'],[
 ('Konoha','O filho e a ausência','A rotina de Naruto como Hokage afeta a convivência em família. A rebeldia de Boruto também expressa o desejo de atenção e de compreender melhor o pai.',False,'01_1745'),
 ('O novo Time 7','Aprender com outras gerações','Ao lado de Sarada e Mitsuki, participa da formação de um novo Time 7. O contato com Konohamaru e Sasuke amplia seu aprendizado e muda sua relação com as responsabilidades de um shinobi.',False,'01_1745'),
 ('Desafios','Escolher diante das consequências','Os acontecimentos do Exame Chūnin e o confronto com os Ōtsutsuki o obrigam a rever atalhos e reconhecer seus limites. A compreensão do passado de Naruto passa a integrar seu crescimento.',True,'01_1745'),
 ('Nova fase','Enfrentar o destino','O conflito envolvendo Kawaki e as Árvores Divinas transforma radicalmente sua posição no mundo. Boruto procura proteger seus vínculos enquanto enfrenta as consequências dessa nova realidade.',True,'01_1745')])
bio('Sarada Uchiha','Olhar para a vila e imaginar seu futuro','Sarada reúne a herança dos Uchiha à vontade de seguir o exemplo de Naruto. Seu objetivo é se tornar Hokage e proteger as pessoas à sua volta.','sarada',['01_1750'],[
 ('Origens','Entre duas histórias','Filha de Sasuke e Sakura, Sarada cresce ligada ao passado do Time 7. As perguntas sobre sua família fazem parte de uma procura por compreender quem é e o que deseja realizar.',False,'01_1750'),
 ('Time 7','Um objetivo próprio','Na equipe com Boruto e Mitsuki, desenvolve suas habilidades e a cooperação em missão. A admiração por Naruto oferece uma direção que vai além das expectativas colocadas sobre seu sobrenome.',False,'01_1750'),
 ('Continuidade','Proteger os vínculos','Os conflitos que atingem a nova geração exigem que tome decisões difíceis. Sua disposição para defender os companheiros mantém o sonho de liderança associado ao cuidado com outras pessoas.',True,'01_1750')])
bio('Deidara','A arte dura o tempo de uma explosão','O integrante da Akatsuki transforma argila e explosões em uma linguagem própria. Seu orgulho artístico atravessa os confrontos e as rivalidades que escolhe alimentar.','deidara',['01_1781'],[
 ('Akatsuki','O artista e a organização','Recrutado para a Akatsuki após enfrentar Itachi, Deidara passa a atuar com suas criações explosivas. A derrota para o Sharingan permanece como um ponto sensível em sua maneira de encarar os Uchiha.',False,'01_1781'),
 ('Confrontos','A obra em movimento','Seu combate combina preparação, mobilidade e criaturas de argila. A confiança em sua visão de arte também produz conflitos de temperamento com seus parceiros.',False,'01_1781'),
 ('Desfecho','O limite do próprio orgulho','No confronto com Sasuke, leva a rivalidade com os Uchiha às últimas consequências. Sua decisão final reúne a busca de reconhecimento e o desejo de transformar a própria existência em uma explosão.',True,'01_1781')])
bio('Sasori','O tempo e a busca de permanência','O mestre de marionetes de Suna procura uma forma de arte que sobreviva ao tempo. Sua história está ligada à solidão, à perda e ao aprendizado com Chiyo.','sasori',['01_1641'],[
 ('Infância','A ausência e as primeiras marionetes','Depois de perder os pais, Sasori aprende com a avó a construir marionetes. Suas primeiras tentativas de recriar um abraço familiar revelam a ligação entre a técnica e a dor da ausência.',False,'01_1641'),
 ('Akatsuki','A procura pela arte eterna','Sua investigação o leva das marionetes comuns às marionetes humanas. O desejo de permanência passa a transformar tanto seu arsenal quanto a relação com o próprio corpo.',True,'01_1641'),
 ('O reencontro','Chiyo e Sakura','O confronto com a avó e Sakura reúne a habilidade técnica acumulada e os vínculos que ele tentou abandonar. As figuras de seus pais retornam ao centro de seu desfecho.',True,'01_1641')])
bio('Sakumo Hatake','Um legado além da missão','Conhecido como Presa Branca, o pai de Kakashi deixa uma história em que a escolha pelos companheiros altera tanto a reputação quanto a vida da família.','kakashi',['01_1875'],[
 ('Konoha','A Presa Branca','Sakumo se torna conhecido por sua atuação em combate e pela lâmina de chakra branco. Sua reputação faz parte das expectativas que cercam a infância de Kakashi.',False,'01_1875'),
 ('Escolha','O preço de proteger companheiros','Ao colocar os companheiros acima de uma missão, sofre rejeição e perde o apoio que sustentava sua posição. A tragédia resultante marca profundamente a maneira como Kakashi entende o dever.',True,'01_1875'),
 ('Reencontro','O entendimento que faltava','No encontro com o filho após a batalha contra Pain, os dois conseguem conversar sobre culpa e compreensão. O reconhecimento de Kakashi permite que Sakumo encontre paz em relação à própria decisão.',True,'01_1875')])
bio('Rock Lee','O talento de não desistir','Lee procura provar que esforço, taijutsu e confiança podem sustentar uma vida ninja. A relação com Guy dá forma ao seu treinamento e à sua perseverança.','lee',['01_1652'],[
 ('Formação','Um caminho pelo taijutsu','Ao lado de Neji e Tenten, dedica-se aos ensinamentos de Guy. Sua dificuldade com ninjutsu e genjutsu o leva a construir uma especialidade baseada em treinamento físico e combate corporal.',False,'01_1652'),
 ('Exame Chūnin','O teste contra Gaara','O confronto mostra a velocidade conquistada com disciplina e a aplicação dos Portões Internos. Mesmo ferido, Lee insiste em se levantar e continuar perseguindo o objetivo de ser um grande shinobi.',False,'01_1652'),
 ('Retorno','A decisão de continuar','As lesões o colocam diante de uma cirurgia arriscada. Com o apoio de Guy, escolhe tentar voltar e mais tarde auxilia os companheiros, mantendo a própria determinação como parte central de sua história.',True,'01_1652')])

# Dados descritivos apenas para técnicas presentes no catálogo local.
TECH=[]
def tech(name,pt,category,animation,description,source):
    catalog=json.loads((ROOT/'data/processed/json/jutsus.json').read_text(encoding='utf-8'))
    matches=[j for j in catalog if j['nome'].casefold()==name.casefold()]
    if not matches:print('Técnica não encontrada:',name);return
    description=re.sub(r'\s+(?:A animação|A ilustração|A cena ilustrativa|A sequência ilustrativa).*','',description)
    for row in matches:TECH.append({'jutsu_id':row['jutsu_id'],'nome_pt':pt,'categoria':category,'animacao':animation,'descricao':description,'url_fonte':BASE+source,'tipo_midia':'Texto editorial; sequência original do jogo quando disponível para o personagem'})
tech('Rasengan','Rasengan','Ninjutsu','rasengan','Uma esfera de chakra em rotação concentrada na mão. A ilustração destaca a formação e a liberação dessa energia.','01_1643')
tech('Shadow Clone Technique','Clones das Sombras','Ninjutsu','clones','O chakra é dividido para criar cópias físicas do usuário. A experiência adquirida por uma cópia retorna ao original quando ela se desfaz.','01_1694')
tech('Multiple Shadow Clone Technique','Múltiplos Clones das Sombras','Ninjutsu','clones','A variação amplia a quantidade de cópias físicas criadas. A demonstração usa um pequeno grupo de silhuetas para representar a multiplicação.','01_1610')
tech('Chidori','Chidori','Ninjutsu','lightning','Chakra de relâmpago se concentra na mão para um ataque direto. A cena ilustrativa representa a concentração elétrica e o avanço.','01_1856')
tech('Lightning Cutter','Corte Relâmpago','Ninjutsu','lightning','Técnica associada a Kakashi, com concentração de chakra de relâmpago. Os arcos elétricos da animação são uma representação visual simplificada.','01_1903')
tech('Fire Release: Great Fireball Technique','Estilo Fogo · Grande Bola de Fogo','Ninjutsu','fire','Uma emissão de fogo projetada à frente do usuário. A demonstração representa a preparação e a expansão da chama.','01_1856')
tech('Amaterasu','Amaterasu','Dōjutsu','amaterasu','Chamas negras associadas ao Mangekyō Sharingan. A animação estiliza o foco do olhar e o surgimento das chamas, sem reproduzir uma cena do anime.','01_1814')
tech('Tsukuyomi','Tsukuyomi','Genjutsu','eye','Um genjutsu ocular de Itachi. O ambiente em vermelho e a mudança de percepção na animação são recursos ilustrativos da interface.','01_1814')
tech('Susanoo','Susanoo','Dōjutsu','susanoo','Uma manifestação de chakra ligada ao poder ocular dos Uchiha. A demonstração representa uma proteção etérea ao redor do usuário.','01_1858')
tech('Kamui','Kamui','Dōjutsu','vortex','Um ninjutsu espaço-temporal associado ao Mangekyō Sharingan. O vórtice da demonstração representa uma distorção espacial.','01_1904')
tech('Flying Thunder God Technique','Deus Voador do Trovão','Espaço-tempo','teleport','O usuário se desloca para coordenadas previamente marcadas. A animação usa duas marcas para representar esse deslocamento.','01_1694')
tech('Summoning Technique','Técnica de Invocação','Ninjutsu','summon','Uma invocação traz um aliado vinculado ao usuário. A ilustração mostra o gesto, o selo e a fumaça do aparecimento, sem atribuir a mesma criatura a todos.','01_1643')
tech('Mystical Palm Technique','Palma Mística','Ninjutsu médico','healing','Chakra concentrado nas mãos é aplicado em tratamento. O brilho verde e os pulsos na demonstração são uma interpretação visual do ninjutsu médico.','01_1743')
tech('Creation Rebirth','Renascimento da Criação','Ninjutsu médico','healing','Uma técnica regenerativa associada ao treinamento de Tsunade. A demonstração destaca a liberação de chakra como recurso ilustrativo.','01_1743')
tech('Eight Gates','Oito Portões','Taijutsu','gates','A liberação dos portões internos eleva o esforço físico e os riscos para o corpo. A demonstração representa a intensificação de uma aura, sem quantificar poder.','01_1673')
tech('Strong Fist','Punho Forte','Taijutsu','taijutsu','Um estilo de combate corporal associado a golpes físicos. O pequeno ciclo de movimento representa uma sequência ilustrativa de ataque.','01_1652')
tech('Gentle Fist','Punho Gentil','Taijutsu','taijutsu','O estilo dos Hyūga combina percepção e controle preciso de chakra no combate próximo. A demonstração usa movimentos curtos e concentrados.','01_1817')
tech('Byakugan','Byakugan','Dōjutsu','byakugan','A habilidade ocular dos Hyūga está ligada à percepção de chakra. O círculo de visão da animação é um símbolo ilustrativo, sem escala de alcance.','01_1668')
tech('Shadow Imitation Technique','Imitação das Sombras','Ninjutsu','shadow','A sombra do usuário se estende e pode conectar seus movimentos aos de um alvo. A cena estiliza a ligação entre duas silhuetas.','01_1910')
tech('Kotoamatsukami','Kotoamatsukami','Genjutsu','eye','O poder ocular de Shisui tem influência decisiva na trajetória de Itachi. A demonstração representa o olhar e uma atmosfera de ilusão.','01_1625')

for name,rows in [('biografias_curadas',BIOS),('historia_personagem',HISTORY),('tecnicas_curadas',TECH)]:
    (OUT/(name+'.json')).write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
